	label: string;
	color: string;
	count: number;
	children: HierarchyNode[];
	/* Only present on leaf nodes (level-3 topics). */
	topic?: string;
}

const CATEGORY_PARENTS: Record<string, { key: string; label: string; color: string }> = {
