/**
 * Build a 3-level tree from flat artifact groups.
 * Level 1 = parent domain, Level 2 = category, Level 3 = individual topics.
 */
export function buildTopicHierarchy(groups: TopicArtifactGroup[]): HierarchyNode {
	const root: HierarchyNode = { key: "root", label: "All Topics", color: "#64748b", count: 0, children: [] };

	for (const group of groups) {
		const parentMeta = CATEGORY_PARENTS[group.key] ?? { key: "general-domain", label: "General", color: "#64748b" };
		let parent = root.children.find((c) => c.key === parentMeta.key);
		if (!parent) {
			parent = { key: parentMeta.key, label: parentMeta.label, color: parentMeta.color, count: 0, children: [] };
			root.children.push(parent);
		}
		const categoryNode: HierarchyNode = {
			key: group.key,
			label: group.label,
			color: group.color,
			count: group.count,
			children: group.topics.map((t) => ({
				key: `topic-${t.topic}`,
				label: t.topic,
				color: group.color,
				count: t.count,
				children: [],
				topic: t.topic,
			})),
		};
		parent.children.push(categoryNode);
		parent.count += group.count;
		root.count += group.count;
	}

	// Sort each level by count desc, then label asc
	root.children.sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
	for (const parent of root.children) {
		parent.children.sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
	}

	return root;
}

export function buildTopicArtifactGroups(
	artifacts: TopicArtifactInput[],
	assignments?: Record<string, string>,
): TopicArtifactGroup[] {
	const groups = new Map<string, TopicArtifactGroup>();

	for (const artifact of artifacts) {
		const topic = (artifact.topic ?? "").trim();
		if (!topic) continue;
		const category = categorizeUsageTopic(topic, assignments);
		const group = groups.get(category.key) ?? {
			key: category.key,
			label: category.label,
			color: category.color,
			count: 0,
			topics: [],
			types: { plan: 0, map: 0, animation: 0, verification: 0 },
		};
		group.count += 1;
		group.types[artifact.type] += 1;
		const existingTopic = group.topics.find((entry) => entry.topic.toLowerCase() === topic.toLowerCase());
		if (existingTopic) {
			existingTopic.count += 1;
		} else {
			group.topics.push({ topic, count: 1 });
		}
		groups.set(category.key, group);
	}

	return [...groups.values()]
		.map((group) => ({
			...group,
			topics: group.topics.sort((a, b) => b.count - a.count || a.topic.localeCompare(b.topic)),
		}))
		.sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
}

import type { FeedbackEntry, LearnerState } from "../keating/storage";
import type { SessionMetadata } from "../types/session";

export type LearnerSession = LearnerState["sessions"][number];
export type ModelUsageBasis = "tokens" | "messages";

export interface ModelUsageEntry {
	key: string;
	label: string;
	provider: string;
	modelId: string;
	sessions: number;
	messages: number;
	tokens: number;
	cost: number;
	value: number;
	share: number;
	color: string;
}

export interface ModelUsageBreakdown {
	basis: ModelUsageBasis;
	total: number;
	entries: ModelUsageEntry[];
}

export interface FeedbackSignalGroup {
	label: string;
	count: number;
	color: string;
	entries: FeedbackEntry[];
}

const DEFAULT_OPEN_SESSION_DISPLAY_MS = 30 * 60 * 1000;
const MODEL_USAGE_COLORS = ["#6366f1", "#22c55e", "#f97316", "#06b6d4", "#d946ef", "#eab308", "#ef4444"];

export function getPrimaryCurriculumTopic(session: LearnerSession): string | null {
	const topic = session.topicsCovered?.find((entry) => entry.trim().length > 0)?.trim();
	return topic ?? null;
}

export function getVisibleCurriculumSessions(sessions: LearnerState["sessions"] | undefined): LearnerSession[] {
	return [...(sessions ?? [])]
		.filter((session) => typeof session.startedAt === "number" && getPrimaryCurriculumTopic(session) !== null)
		.sort((a, b) => a.startedAt - b.startedAt);
}

export function getCurriculumDisplayEnd(session: LearnerSession, now = Date.now()): number {
	if (typeof session.endedAt === "number" && session.endedAt >= session.startedAt) {
		return session.endedAt;
	}
	return Math.min(now, session.startedAt + DEFAULT_OPEN_SESSION_DISPLAY_MS);
}

export function hasMeaningfulPolicyScores(scores: Array<{ score: number }>): boolean {
	return scores.some((entry) => entry.score > 0);
}

export function aggregateFeedback(entries: FeedbackEntry[]): FeedbackSignalGroup[] {
	const definitions: Array<{ signal: FeedbackEntry["signal"]; label: string; color: string }> = [
		{ signal: "thumbs-up", label: "Confident", color: "#22c55e" },
		{ signal: "thumbs-down", label: "Off-track", color: "#ef4444" },
		{ signal: "confused", label: "Confused", color: "#f97316" },
	];
	return definitions.flatMap((definition) => {
		const matching = entries
			.filter((entry) => entry.signal === definition.signal)
			.sort((left, right) => right.createdAt - left.createdAt);
		return matching.length > 0
			? [{ ...definition, count: matching.length, entries: matching }]
			: [];
	});
}

function sessionTokenCount(session: SessionMetadata): number {
	return session.usage.totalTokens || session.usage.input + session.usage.output;
}

function modelLabel(session: SessionMetadata): { key: string; label: string; provider: string; modelId: string } {
	const provider = session.modelProvider?.trim() || "unknown";
	const modelId = session.modelId?.trim() || "unknown";
	const label = session.modelName?.trim() || (modelId === "unknown" ? "Unknown model" : modelId);
	return {
		key: `${provider}::${modelId}`,
		label,
		provider,
		modelId,
	};
}

function withShares(entries: ModelUsageEntry[], total: number): ModelUsageEntry[] {
	return entries.map((entry, index) => ({
		...entry,
		share: total > 0 ? entry.value / total : 0,
		color: entry.color || MODEL_USAGE_COLORS[index % MODEL_USAGE_COLORS.length],
	}));
}

export function buildModelUsageBreakdown(
	sessions: SessionMetadata[],
	maxEntries = 6,
): ModelUsageBreakdown {
	const totalTokens = sessions.reduce((sum, session) => sum + sessionTokenCount(session), 0);
	const basis: ModelUsageBasis = totalTokens > 0 ? "tokens" : "messages";
	const byModel = new Map<string, ModelUsageEntry>();

	for (const session of sessions) {
		const model = modelLabel(session);
		const tokens = sessionTokenCount(session);
		const current = byModel.get(model.key) ?? {
			...model,
			sessions: 0,
			messages: 0,
			tokens: 0,
			cost: 0,
			value: 0,
			share: 0,
			color: "",
		};
		current.sessions += 1;
		current.messages += session.messageCount;
		current.tokens += tokens;
		current.cost += session.usage.cost.total;
		current.value += basis === "tokens" ? tokens : session.messageCount;
		byModel.set(model.key, current);
	}

	const sorted = Array.from(byModel.values()).sort((a, b) => b.value - a.value);
	const visible = sorted.slice(0, maxEntries);
	const overflow = sorted.slice(maxEntries);
	if (overflow.length > 0) {
		visible.push({
			key: "other",
			label: "Other models",
			provider: "mixed",
			modelId: "other",
			sessions: overflow.reduce((sum, entry) => sum + entry.sessions, 0),
			messages: overflow.reduce((sum, entry) => sum + entry.messages, 0),
			tokens: overflow.reduce((sum, entry) => sum + entry.tokens, 0),
			cost: overflow.reduce((sum, entry) => sum + entry.cost, 0),
			value: overflow.reduce((sum, entry) => sum + entry.value, 0),
			share: 0,
			color: "",
		});
	}

	const total = visible.reduce((sum, entry) => sum + entry.value, 0);
	return {
		basis,
		total,
		entries: withShares(visible, total),
	};
}

