import type { PortableLearnerData } from "@keating/learner-contracts";
import type { PersistedAppState, ProviderId } from "./types";

export interface TopicActivity {
  key: string;
  label: string;
  source: string;
  lastStudiedAt: number;
  turns: number;
}

export interface ModelActivity {
  key: string;
  provider: string;
  model: string;
  replies: number;
  tokens: number;
}

export interface MobileUsageSummary {
  lessons: number;
  messages: number;
  assistantReplies: number;
  attachments: number;
  artifacts: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  reportedCostUsd: number;
  helpful: number;
  missed: number;
  topics: TopicActivity[];
  models: ModelActivity[];
  recentLessons: Array<{ id: string; title: string; updatedAt: number; messages: number }>;
}

function topicKey(label: string): string {
  return label.trim().toLocaleLowerCase().replace(/\s+/g, " ");
}

export function buildMobileUsageSummary(state: PersistedAppState): MobileUsageSummary {
  const meaningfulSessions = state.sessions.filter((session) => session.messages.length > 0);
  const allMessages = meaningfulSessions.flatMap((session) => session.messages);
  const assistantMessages = allMessages.filter((message) => message.role === "assistant");
  const topicMap = new Map<string, TopicActivity>();

  for (const session of meaningfulSessions) {
    if (session.title === "New lesson" || !session.title.trim()) continue;
    const key = topicKey(session.title);
    const prior = topicMap.get(key);
    topicMap.set(key, {
      key,
      label: session.title,
      source: prior?.source ?? "lesson title",
      lastStudiedAt: Math.max(prior?.lastStudiedAt ?? 0, session.updatedAt),
      turns: (prior?.turns ?? 0) + session.messages.length,
    });
  }
  for (const artifact of state.artifacts) {
    if (!artifact.topic?.trim()) continue;
    const key = topicKey(artifact.topic);
    const prior = topicMap.get(key);
    topicMap.set(key, {
      key,
      label: artifact.topic,
      source: "generated artifact",
      lastStudiedAt: Math.max(prior?.lastStudiedAt ?? 0, artifact.createdAt),
      turns: prior?.turns ?? 0,
    });
  }

  const modelMap = new Map<string, ModelActivity>();
  for (const message of assistantMessages) {
    if (!message.provider || !message.model) continue;
    const key = `${message.provider}:${message.model}`;
    const prior = modelMap.get(key);
    modelMap.set(key, {
      key,
      provider: message.provider,
      model: message.model,
      replies: (prior?.replies ?? 0) + 1,
      tokens: (prior?.tokens ?? 0) + (message.usage?.totalTokens ?? 0),
    });
  }

  return {
    lessons: meaningfulSessions.length,
    messages: allMessages.length,
    assistantReplies: assistantMessages.length,
    attachments: allMessages.reduce((total, message) => total + (message.attachments?.length ?? 0), 0),
    artifacts: state.artifacts.length,
    inputTokens: assistantMessages.reduce((total, message) => total + (message.usage?.inputTokens ?? 0), 0),
    outputTokens: assistantMessages.reduce((total, message) => total + (message.usage?.outputTokens ?? 0), 0),
    totalTokens: assistantMessages.reduce((total, message) => total + (message.usage?.totalTokens ?? 0), 0),
    reportedCostUsd: assistantMessages.reduce((total, message) => total + (message.usage?.costUsd ?? 0), 0),
    helpful: state.learnerFeedback.helpful,
    missed: state.learnerFeedback.missed,
    topics: [...topicMap.values()].sort((a, b) => b.lastStudiedAt - a.lastStudiedAt),
    models: [...modelMap.values()].sort((a, b) => b.replies - a.replies || b.tokens - a.tokens),
    recentLessons: meaningfulSessions
      .map((session) => ({ id: session.id, title: session.title, updatedAt: session.updatedAt, messages: session.messages.length }))
      .sort((a, b) => b.updatedAt - a.updatedAt)
      .slice(0, 8),
  };
}

/** Builds the same view from the cross-surface SQLite/portable record boundary. */
export function buildRepositoryUsageSummary(data: PortableLearnerData): MobileUsageSummary {
  const meaningfulSessions = data.sessions.filter((session) => session.messages.length > 0);
  const topicMap = new Map<string, TopicActivity>();
  const sessionsById = new Map(data.sessions.map((session) => [session.id, session]));
  for (const evidence of data.topicEvidence) {
    const key = topicKey(evidence.topic);
    const prior = topicMap.get(key);
    const session = evidence.reference?.kind === "session" ? sessionsById.get(evidence.reference.id) : undefined;
    topicMap.set(key, {
      key,
      label: evidence.topic,
      source: evidence.provenance,
      lastStudiedAt: Math.max(prior?.lastStudiedAt ?? 0, Date.parse(evidence.createdAt)),
      turns: (prior?.turns ?? 0) + (session?.messages.length ?? 0),
    });
  }

  const modelMap = new Map<string, ModelActivity>();
  let inputTokens = 0;
  let outputTokens = 0;
  let totalTokens = 0;
  let reportedCostUsd = 0;
  for (const event of data.usageEvents) {
    const provider = event.provider;
    const key = `${provider}:${event.model}`;
    const eventInput = event.providerReported.inputTokens ?? 0;
    const eventOutput = event.providerReported.outputTokens ?? 0;
    const eventTotal = event.providerReported.totalTokens ?? eventInput + eventOutput;
    const prior = modelMap.get(key);
    modelMap.set(key, {
      key,
      provider,
      model: event.model,
      replies: (prior?.replies ?? 0) + 1,
      tokens: (prior?.tokens ?? 0) + eventTotal,
    });
    inputTokens += eventInput;
    outputTokens += eventOutput;
    totalTokens += eventTotal;
    reportedCostUsd += event.providerReported.costUsd ?? 0;
  }

  return {
    lessons: meaningfulSessions.length,
    messages: meaningfulSessions.reduce((total, session) => total + session.messages.length, 0),
    assistantReplies: meaningfulSessions.reduce((total, session) =>
      total + session.messages.filter((message) => message.role === "assistant").length, 0),
    attachments: meaningfulSessions.reduce((total, session) =>
      total + session.messages.reduce((sessionTotal, message) => sessionTotal + (message.attachments?.length ?? 0), 0), 0),
    artifacts: data.artifacts.length,
    inputTokens,
    outputTokens,
    totalTokens,
    reportedCostUsd,
    helpful: data.feedbackEvents.filter((event) => event.rating === "helpful").length,
    missed: data.feedbackEvents.filter((event) => event.rating === "missed").length,
    topics: [...topicMap.values()].sort((left, right) => right.lastStudiedAt - left.lastStudiedAt),
    models: [...modelMap.values()].sort((left, right) => right.replies - left.replies || right.tokens - left.tokens),
    recentLessons: meaningfulSessions
      .map((session) => ({
        id: session.id,
        title: session.title,
        updatedAt: Date.parse(session.updatedAt),
        messages: session.messages.length,
      }))
      .sort((left, right) => right.updatedAt - left.updatedAt)
      .slice(0, 8),
  };
}

		if (!files) {
			counters.skipped += 1;
			continue;
		}
		const redacted = redactText(summary, options.redact);
		counters.redactions += redacted.count;
		const instruction = `Describe the purpose and exact file impact of the Keating sandbox checkpoint: ${commit.message}`;
		const messages = [
			{ role: "user" as const, content: instruction },
			{ role: "assistant" as const, content: redacted.text },
		];
		examples.push({
			id: `sandbox-commit-${planSafeId(commit.id)}`,
			source: "sandbox",
			kind: "checkpoint",
			commitId: commit.id,
			instruction,
			output: redacted.text,
			messages,
		});
		conversations?.push({ source: "sandbox", messages });
	}
	return { filesRead, commitsRead };
}

function toChatMlJsonl(conversations: WebConversation[]): string {
	return conversations.map((conversation) => JSON.stringify(
		conversation.envelope
			? { messages: conversation.messages, keating: conversation.envelope }
			: { messages: conversation.messages },
	)).join("\n") + (conversations.length ? "\n" : "");
}

function toAlpacaJsonl(examples: FineTuneExample[]): string {
	return examples.map((example) => JSON.stringify({
		instruction: example.instruction,
		input: example.input ?? "",
		output: example.output,
	})).join("\n") + (examples.length ? "\n" : "");
}

function toJsonl(values: unknown[]): string {
	return values.map((value) => JSON.stringify(value)).join("\n") + (values.length ? "\n" : "");
}

function planSafeId(value: string): string {
	const normalized = value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
	return normalized.slice(0, 80) || "item";
}

function stableHash(value: string): number {
	let hash = 0x811c9dc5;
	for (let index = 0; index < value.length; index += 1) {
		hash ^= value.charCodeAt(index);
		hash = Math.imul(hash, 0x01000193);
	}
	return hash >>> 0;
}

function splitFor(sourceKey: string): TrainingSplit {
	return stableHash(sourceKey) % 10 === 0 ? "validation" : "train";
}

function rewardTurnKey(sessionId?: string, messageTimestamp?: number): string | null {
	return sessionId && typeof messageTimestamp === "number" ? `${sessionId}:${messageTimestamp}` : null;
}

function qualityForTurn(turn?: RewardedTurn): CanonicalTrainingRecord["quality"] {
	if (!turn) return { status: "unscored", recommendedForSft: false, scored: false };
	if (!turn.scored) return { status: "unscored", recommendedForSft: false, scored: false, signals: turn.signals };
	const status: TrainingQualityStatus = turn.reward >= KTO_GOOD_THRESHOLD
		? "accepted"
		: turn.reward <= 0.35
			? "rejected"
			: "review";
	return {
		status,
		recommendedForSft: status === "accepted",
		scored: true,
		reward: turn.reward,
		signals: turn.signals,
	};
}

function buildCanonicalRecords(
	examples: FineTuneExample[],
	rewardedTurns: RewardedTurn[],
	persona: string,
): { records: CanonicalTrainingRecord[]; duplicateCount: number } {
	const turnsByKey = new Map<string, RewardedTurn>();
	for (const turn of rewardedTurns) {
		const key = rewardTurnKey(turn.sessionId, turn.messageTimestamp);
		if (key) turnsByKey.set(key, turn);
	}
	const seen = new Set<string>();
	const records: CanonicalTrainingRecord[] = [];
	let duplicateCount = 0;
	for (const example of examples) {
		const turnKey = rewardTurnKey(example.sessionId, example.messageTimestamp);
		const turn = turnKey ? turnsByKey.get(turnKey) : undefined;
		const rawMessages = turn
			? [...turn.context, { role: "assistant" as const, content: turn.completion }]
			: (example.messages ?? [
				{ role: "user" as const, content: example.instruction },
				{ role: "assistant" as const, content: example.output },
			]);
		const baseMessages = rawMessages.map((message) => ({ role: message.role, content: message.content }));
		const messages = !turn && example.source === "session" && persona.trim()
			? [{ role: "system" as const, content: persona.trim() }, ...baseMessages]
			: baseMessages;
		const completion = messages.at(-1)?.content ?? example.output;
		const prompt = messages.slice(0, -1);
		const fingerprint = JSON.stringify([...prompt.map((message) => [message.role, message.content.trim()]), ["assistant", completion.trim()]]);
		if (seen.has(fingerprint)) {
			duplicateCount += 1;
			continue;
		}
		seen.add(fingerprint);
		const quality = example.source === "sandbox"
			? { status: "reference" as const, recommendedForSft: false, scored: false }
			: example.source === "artifact"
				? { status: "accepted" as const, recommendedForSft: true, scored: false }
				: qualityForTurn(turn);
		records.push({
			schemaVersion: 2,
			id: `${example.id}-${stableHash(fingerprint).toString(36)}`,
			split: splitFor(example.sessionId ?? example.path ?? example.commitId ?? example.id),
			task: quality.status === "rejected" ? "preference-learning" : quality.status === "reference" ? "reference" : "supervised-finetuning",
			source: {
				type: example.source,
				kind: example.kind,
				topic: example.topic,
				sessionId: example.sessionId,
				sessionTitle: example.sessionTitle,
				messageTimestamp: example.messageTimestamp,
				model: example.model,
				thinkingLevel: example.thinkingLevel,
				path: example.path,
				commitId: example.commitId,
			},
			messages,
			prompt,
			completion,
			quality,
			metrics: {
				promptCharacters: prompt.reduce((sum, message) => sum + message.content.length, 0),
				completionCharacters: completion.length,
				messageCount: messages.length,
			},
		});
	}
	return { records, duplicateCount };
}

function dedupeExamples(examples: FineTuneExample[]): { examples: FineTuneExample[]; duplicateCount: number } {
	const seen = new Set<string>();
	const unique: FineTuneExample[] = [];
	let duplicateCount = 0;
	for (const example of examples) {
		const fingerprint = JSON.stringify([
			example.instruction.trim(),
			(example.input ?? "").trim(),
			example.output.trim(),
		]);
		if (seen.has(fingerprint)) {
			duplicateCount += 1;
			continue;
		}
		seen.add(fingerprint);
		unique.push(example);
	}
	return { examples: unique, duplicateCount };
}

function qualityCounts(records: CanonicalTrainingRecord[]): Record<TrainingQualityStatus, number> {
	const counts: Record<TrainingQualityStatus, number> = {
		accepted: 0,
		unscored: 0,
		review: 0,
		rejected: 0,
		reference: 0,
	};
	for (const record of records) counts[record.quality.status] += 1;
	return counts;
}

function lineCount(jsonl?: string): number {
	return jsonl ? jsonl.trim().split("\n").filter(Boolean).length : 0;
}

export async function buildWebFineTuneExportFromSources(
	sources: WebExportSources,
	options: WebFineTuneExportOptions,
): Promise<WebFineTuneExportResult> {
	const examples: FineTuneExample[] = [];
	const rewardedTurns: RewardedTurn[] = [];
	const normalizedSessions = new Map<string, NormalizedSessionResult>();
	const counters = { redactions: 0, skipped: 0 };
	const includeArtifacts = options.source === "all" || options.source === "artifacts";
	const includeSessions = options.source === "all" || options.source === "sessions";
	const includeSandbox = options.source === "all" || options.source === "sandbox";
	let normalizedPersona = "";
	let artifactsRead = 0;
	let sessionsRead = 0;
